void Monstey_Word(std::vector<std::uint8_t>&b,std::size_t at,Monstey_U32 v){if(at+4>b.size())throw std::runtime_error("fixture word");for(unsigned i=0;i<4;++i)b[at+i]=static_cast<std::uint8_t>(v>>(8*i));}
struct Monstey_Guard{Monstey_State*state;explicit Monstey_Guard(Monstey_State*s):state(s){}~Monstey_Guard(){state->old_retired=true;state->trace.push_back("retire-old");state->rows[900]++;}};
template<bool Product>using Monstey_Holder=std::conditional_t<Product,Monstey::Monstey_FearDbNameCompare,Monstey_ReferenceTarget>;
template<bool Product>Monstey_U32 Monstey_Invoke(bool open,Monstey_State&s,Monstey_U32 query,Monstey_U32 count,const Monstey_Holder<Product>&h){if constexpr(Product){if(open)return Monstey::Monstey_FearDbOpenExisting(s.resources,{0x9000,s.names},query,h);return Monstey::Monstey_FearDbBinaryNameSearch({0x4000,s.rows},0x4000,count,query,h);}else{if(open)return Monstey_ReferenceOpen(s.resources,{0x9000,s.names},query,h);return Monstey_ReferenceNames({0x4000,s.rows},0x4000,count,query,h);}}
template<bool Product>Monstey_State Monstey_Run(bool open,unsigned profile,Monstey_U32 count=7,Monstey_I32 first=1){
 Monstey_State s;s.resources.cache.reserve(32);for(unsigned i=0;i<8;++i){Monstey::Monstey_FearDbPackedImage image;image.base=0x20000+0x1000*i;image.database=image.base+0x100;image.used_bytes=512;image.allocation.assign(512,0xA5);Monstey_Word(image.allocation,0x104,0xA000+4*i);Monstey_Word(image.allocation,0x110,0xFFFFFFFD+i);s.resources.allocations.push_back(std::move(image));if(i<3)s.resources.cache.push_back(s.resources.allocations.back().database);}for(unsigned i=0;i<32;++i)Monstey_Word(s.rows,16*i,0xB000+4*i);s.names[0]='x';s.names[1]=0;Monstey_U32 query=open?0x9000u:0xC000u;
 if(profile==8){for(auto&i:s.resources.allocations)Monstey_Word(i.allocation,0x104,0);for(unsigned i=0;i<32;++i)Monstey_Word(s.rows,16*i,0);}
 if(profile==9)query=0;if(profile==10){s.names[0]=0;count=0;}if(profile==11)query=open?0x8FFFu:0xC000u;if(profile==12){s.resources.allocations[0].allocation.resize(0x106);s.rows.resize(2);}if(profile==14){query=0;for(unsigned i=0;i<32;++i)Monstey_Word(s.rows,16*i,0);}if(profile==15){for(unsigned i=0;i<32;++i)Monstey_Word(s.rows,16*i,0);}
 if(profile==21){s.resources.allocations[0].allocation.resize(0x106);s.rows.resize(2);}if(profile==23){query=0;s.resources.allocations.clear();s.resources.cache.assign(1,0);s.rows.clear();count=0;}
 Monstey_Holder<Product>h;auto guard=std::make_shared<Monstey_Guard>(&s);std::function<Monstey_U32()>reenter;
 h=[&,guard,step=0u](Monstey_U32 a,Monstey_U32 b)mutable->Monstey_I32{const auto n=++step;++s.old_calls;s.trace.push_back("old:"+std::to_string(n)+":"+std::to_string(a)+":"+std::to_string(b)+":"+(s.old_retired?"retired":"alive"));s.rows[850]^=static_cast<std::uint8_t>(n);
  if(n==1){if(profile==1||profile==2||profile==3){if(profile==2)h=Monstey_Holder<Product>{};else h=[&](Monstey_U32 x,Monstey_U32 y){++s.new_calls;s.trace.push_back("new:"+std::to_string(x)+":"+std::to_string(y)+":"+(s.old_retired?"retired":"alive"));s.rows[851]++;return 0;};s.trace.push_back(guard&& !s.old_retired?"active-old-held":"active-old-destroyed");}
   if(profile==3){s.rows[852]=0x55;throw std::runtime_error("explicit comparator throw");}
   if(profile==4&&!s.reentered){s.reentered=true;s.trace.push_back("enter-recursion");(void)reenter();s.trace.push_back("leave-recursion");}
   if(open&&profile==5)s.resources.cache.push_back(s.resources.allocations[3].database);
   if(open&&profile==6)s.resources.cache.resize(0);
   if(open&&profile==7){s.resources.cache[0]=s.resources.allocations[2].database;return 0;}
   if(open&&profile==17){auto copy=s.resources.cache;copy.reserve(1000);s.resources.cache.swap(copy);}
  }
  if(profile==16)return first;
  if(profile==0||profile==18||profile==19)return n>=3?0:1;
  if(open&&profile==5)return b==0xA00C?0:1;
  return 1;
 };guard.reset();reenter=[&](){return Monstey_Invoke<Product>(open,s,query,count,h);};if(profile==8||profile==14||profile==15||profile==20||profile==21||profile==23)h=Monstey_Holder<Product>{};
 try{s.result=Monstey_Invoke<Product>(open,s,query,count,h);if(profile==18||profile==19){s.trace.push_back("phase-one:"+std::to_string(s.result));if(profile==18)s.result=Monstey_Invoke<Product>(open,s,query,count,h);else{auto duplicate=h;s.result=Monstey_Invoke<Product>(open,s,query,count,duplicate);s.trace.push_back("phase-two:"+std::to_string(s.result));s.result=Monstey_Invoke<Product>(open,s,query,count,h);}}}catch(const Monstey_ReferenceFault&e){s.error=true;s.fault_address=e.address;s.fault_width=e.width;s.fault_write=e.writing;}catch(const Monstey::Monstey_FearDbFault&e){s.error=true;s.fault_address=e.address;s.fault_width=e.width;s.fault_write=e.writing;}catch(const std::exception&){s.error=true;}h=Monstey_Holder<Product>{};return s;
}
template<bool Product>Monstey_State Monstey_FaultCase(bool open,unsigned extent,bool nullQuery=false,bool nullName=false){
 Monstey_State s;s.names[0]='x';s.names[1]=0;Monstey_Holder<Product>h;h=[&](Monstey_U32,Monstey_U32){++s.old_calls;s.trace.push_back("compare");s.rows[901]++;return 0;};
 if(open){Monstey::Monstey_FearDbPackedImage image;image.base=0x20000;image.database=0x20100;image.used_bytes=extent;image.allocation.assign(extent,0xA5);if(extent>=264)Monstey_Word(image.allocation,260,0xA000);if(extent>=276)Monstey_Word(image.allocation,272,0xFFFFFFFF);s.resources.allocations.push_back(std::move(image));s.resources.cache.push_back(0x20100);}else{for(unsigned i=0;i<32;++i)Monstey_Word(s.rows,16*i,nullName?0u:0xB000u+4*i);}
 try{if(open){if constexpr(Product)s.result=Monstey::Monstey_FearDbOpenExisting(s.resources,{0x9000,s.names},0x9000,h);else s.result=Monstey_ReferenceOpen(s.resources,{0x9000,s.names},0x9000,h);}else{Monstey::Monstey_FearDbMemory m{0x4000,std::span<const std::uint8_t>(s.rows).first(extent)};if constexpr(Product)s.result=Monstey::Monstey_FearDbBinaryNameSearch(m,0x4000,7,nullQuery?0u:0xC000u,h);else s.result=Monstey_ReferenceNames(m,0x4000,7,nullQuery?0u:0xC000u,h);}}catch(const Monstey_ReferenceFault&e){s.error=true;s.fault_address=e.address;s.fault_width=e.width;s.fault_write=e.writing;}catch(const Monstey::Monstey_FearDbFault&e){s.error=true;s.fault_address=e.address;s.fault_width=e.width;s.fault_write=e.writing;}catch(const std::exception&){s.error=true;}return s;
}
template<bool Product>Monstey_State Monstey_InteriorCase(unsigned offset,unsigned mode){Monstey_State s;s.names[0]='x';s.names[1]=0;Monstey::Monstey_FearDbPackedImage image;image.base=0x20000;image.database=0x20100;image.used_bytes=512;image.allocation.assign(512,0xA5);Monstey_Word(image.allocation,offset+4,1);Monstey_Word(image.allocation,offset+16,0xFFFFFFFF);Monstey_Word(image.allocation,offset+32,0xFFFFFFFF);s.resources.allocations.push_back(std::move(image));s.resources.cache.push_back(0x20000+offset);const auto query=mode==2?0x20000u+offset+4u:0x9000u;Monstey_Holder<Product>h;h=[&](Monstey_U32 a,Monstey_U32 b){++s.old_calls;s.trace.push_back(std::to_string(a)+":"+std::to_string(b));if(mode==1)s.resources.cache[0]+=16;if(mode==2)s.resources.allocations[0].allocation[offset+4]=0;return 0;};const auto filenameMemory=mode==2?s.resources.allocations[0].Memory():Monstey::Monstey_FearDbMemory{0x9000,s.names};try{if constexpr(Product)s.result=Monstey::Monstey_FearDbOpenExisting(s.resources,filenameMemory,query,h);else s.result=Monstey_ReferenceOpen(s.resources,filenameMemory,query,h);}catch(const Monstey_ReferenceFault&e){s.error=true;s.fault_address=e.address;s.fault_width=e.width;s.fault_write=e.writing;}catch(const Monstey::Monstey_FearDbFault&e){s.error=true;s.fault_address=e.address;s.fault_width=e.width;s.fault_write=e.writing;}catch(const std::exception&){s.error=true;}return s;}
void Monstey_Equal(const Monstey_State&a,const Monstey_State&b){Monstey_Check(a.result==b.result&&a.error==b.error&&a.fault_address==b.fault_address&&a.fault_width==b.fault_width&&a.fault_write==b.fault_write,"result/fault prefix");Monstey_Check(a.names==b.names&&a.rows==b.rows&&a.trace==b.trace,"complete borrowed bytes/target trace");Monstey_Check(a.old_calls==b.old_calls&&a.new_calls==b.new_calls&&a.old_retired==b.old_retired,"target counts and retirement");Monstey_Check(a.resources.cache==b.resources.cache,"complete cache order");Monstey_Check(a.resources.allocations.size()==b.resources.allocations.size(),"complete allocation count");for(std::size_t i=0;i<a.resources.allocations.size();++i){const auto&x=a.resources.allocations[i];const auto&y=b.resources.allocations[i];Monstey_Check(x.base==y.base&&x.database==y.database&&x.used_bytes==y.used_bytes&&x.allocation==y.allocation,"complete allocation bytes");}}
void Monstey_SelfCheck(){auto cut=Monstey_FaultCase<false>(true,263);Monstey_Check(cut.error&&cut.fault_address==0x20104&&cut.fault_width==4,"reference DB name operand");cut=Monstey_FaultCase<false>(true,275);Monstey_Check(cut.error&&cut.fault_address==0x20110&&cut.fault_width==4,"reference DB retain operand");cut=Monstey_FaultCase<false>(true,276);Monstey_Check(!cut.error&&cut.result==0x20100&&cut.resources.allocations[0].allocation[272]==0,"reference retain wrap");cut=Monstey_FaultCase<false>(false,51,true,true);Monstey_Check(cut.error&&cut.fault_address==0x4030&&cut.fault_width==4,"reference null branch loads row first");cut=Monstey_FaultCase<false>(false,52,true,true);Monstey_Check(!cut.error&&cut.result==0x4030&&cut.old_calls==0,"reference null branch no comparator");auto repeat=Monstey_Run<false>(true,18);Monstey_Check(!repeat.error&&repeat.result==0x20100&&repeat.old_calls==4,"reference repeated Open state");repeat=Monstey_Run<false>(true,19);Monstey_Check(!repeat.error&&repeat.result==0x20100&&repeat.old_calls==5,"reference copied holder shared state");auto a=Monstey_Run<false>(true,0);Monstey_Check(!a.error&&a.result==0x22100&&a.old_calls==3,"reference open third match");a=Monstey_Run<false>(true,1);Monstey_Check(!a.error&&a.result==0&&a.old_calls==3&&a.new_calls==0,"reference open captured target");a=Monstey_Run<false>(false,1);Monstey_Check(!a.error&&a.result==0x4050&&a.old_calls==1&&a.new_calls==1,"reference names fresh target");a=Monstey_Run<false>(true,7);Monstey_Check(!a.error&&a.result==0x22100,"reference cache entry reload");a=Monstey_Run<false>(true,6);Monstey_Check(a.error&&a.old_calls==1,"reference consumed shortened cache");a=Monstey_Run<false>(true,8);Monstey_Check(!a.error&&a.old_calls==0&&a.result==0,"reference unconsumed missing comparator");a=Monstey_Run<false>(false,14);Monstey_Check(!a.error&&a.result==0x4030&&a.old_calls==0,"reference null query equality");a=Monstey_Run<false>(true,11);Monstey_Check(a.error&&a.fault_address==0x8FFF&&a.fault_width==1,"reference filename first operand");}
