int main(int argc,char**argv){try{if(argc!=2)throw std::runtime_error("report argument");Monstey_SelfCheck();for(bool open:{false,true})for(unsigned profile=0;profile<=23;++profile){const auto reference=Monstey_Run<false>(open,profile);if constexpr(MONSTEY_BIND_PRODUCT!=0)Monstey_Equal(reference,Monstey_Run<true>(open,profile));++Monstey_cases;}
 for(bool open:{false,true})for(auto count:{0u,1u,2u,3u,4u,7u,16u,17u,0x80000000u,0x80000001u,0xFFFFFFFFu})for(auto sign:{std::int32_t(-2147483647-1),-257,-1,0,1,256,2147483647}){const auto reference=Monstey_Run<false>(open,16,count,sign);if constexpr(MONSTEY_BIND_PRODUCT!=0)Monstey_Equal(reference,Monstey_Run<true>(open,16,count,sign));++Monstey_cases;}
 for(unsigned extent=0;extent<=280;++extent){const auto reference=Monstey_FaultCase<false>(true,extent);if constexpr(MONSTEY_BIND_PRODUCT!=0)Monstey_Equal(reference,Monstey_FaultCase<true>(true,extent));++Monstey_cases;}
 for(unsigned extent=0;extent<=128;++extent)for(bool query:{false,true})for(bool name:{false,true}){const auto reference=Monstey_FaultCase<false>(false,extent,query,name);if constexpr(MONSTEY_BIND_PRODUCT!=0)Monstey_Equal(reference,Monstey_FaultCase<true>(false,extent,query,name));++Monstey_cases;}
 for(unsigned offset=0x40;offset<=0xB0;offset+=4)for(unsigned mode=0;mode<3;++mode){const auto reference=Monstey_InteriorCase<false>(offset,mode);if constexpr(MONSTEY_BIND_PRODUCT!=0)Monstey_Equal(reference,Monstey_InteriorCase<true>(offset,mode));++Monstey_cases;}
 std::ofstream out(argv[1]);out<<"{\"status\":\"PASS\",\"product_bound\":"<<(MONSTEY_BIND_PRODUCT?"true":"false")<<",\"cases\":"<<Monstey_cases<<",\"checks\":"<<Monstey_checks<<",\"native_original_entrypoint_invoked\":false}\n";std::cout<<"PASS "<<Monstey_cases<<" cases "<<Monstey_checks<<" checks product="<<MONSTEY_BIND_PRODUCT<<'\n';return 0;}catch(const std::exception&e){std::cerr<<"FAIL "<<e.what()<<'\n';return 1;}}
